import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Scalar-Variable-Basics.md","filePath":"manual-en/CTABLES-Scalar-Variable-Basics.md","lastUpdated":1785684581000}'),l={name:"manual-en/CTABLES-Scalar-Variable-Basics.md"};function i(n,t,s,o,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h4 id="_15-7-1-2-scalar-variables" tabindex="-1">15.7.1.2 Scalar Variables <a class="header-anchor" href="#_15-7-1-2-scalar-variables" aria-label="Permalink to &quot;15.7.1.2 Scalar Variables&quot;">​</a></h4><p>For a categorical variable, <code>CTABLES</code> divides the table into a cell per category. For a scalar variable, <code>CTABLES</code> instead calculates a summary measure, by default the mean, of the values that fall into a cell. For example, if the only variable specified is a scalar variable, then the output is a single cell that holds the mean of all of the data:</p><pre><code>CTABLES /TABLE age.
</code></pre><table tabindex="0"><thead><tr><th></th><th>Mean</th></tr></thead><tbody><tr><td>D1. AGE: What is your age?</td><td>48</td></tr></tbody></table><p>A scalar variable may nest with categorical variables. The following example shows the mean age of survey respondents across gender and language groups:</p><pre><code>CTABLES /TABLE gender &gt; age BY region.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>English</th><th>Spanish</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>Was this interview conducted in English or Spanish?</td><td></td></tr><tr><td></td><td></td><td></td><td>Mean</td><td>Mean</td></tr><tr><td>D1. AGE: What is your age?</td><td>S3a. GENDER:</td><td>Male</td><td>46</td><td>37</td></tr><tr><td>Female</td><td>51</td><td>39</td><td></td><td></td></tr></tbody></table><p>The order of nesting of scalar and categorical variables affects table labeling, but it does not affect the data displayed in the table. The following example shows how the output changes when the nesting order of the scalar and categorical variable are interchanged:</p><pre><code>CTABLES /TABLE age &gt; gender BY region.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>English</th><th>Spanish</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>Was this interview conducted in English or Spanish?</td><td></td></tr><tr><td></td><td></td><td></td><td>Mean</td><td>Mean</td></tr><tr><td>S3a. GENDER:</td><td>Male</td><td>D1. AGE: What is your age?</td><td>46</td><td>37</td></tr><tr><td>Female</td><td>D1. AGE: What is your age?</td><td>51</td><td>39</td><td></td></tr></tbody></table><p>Only a single scalar variable may appear in each section; that is, a scalar variable may not nest inside a scalar variable directly or indirectly. Scalar variables may only appear on one axis within <code>TABLE</code>.</p>`,11)])])}const g=a(l,[["render",i]]);export{b as __pageData,g as default};
